package com.vandorlabs.neoforge.programmer;
import com.vandorlabs.neoforge.credentials.NativeCredentialItems;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.nbt.*;
import net.minecraft.server.level.*;
import net.minecraft.world.*;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.*;
import net.minecraft.world.item.context.UseOnContext;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.ChestBlockEntity;
import net.minecraft.world.phys.*;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.server.ServerStartedEvent;
/** Public registry factories and real vanilla placement/mining; no private prototype registration. */
@EventBusSubscriber(modid="vandorlabs")
public final class ProgrammerCanonicalChecks {
 private static final BlockPos BASE=new BlockPos(9408,110,9408);private static int checks,ticks;private static boolean reading,watch;private static final List<ItemStack> drops=new ArrayList<>();
 private static boolean enabled(){return System.getProperty("vandorlabs.transmitterPhase","").startsWith("programmer-canonical-");}
 private static void need(boolean value,String why){checks++;if(!value)throw new AssertionError("Canonical Programmer: "+why);}
 private static ServerPlayer actor(ServerLevel level){var actor=new net.neoforged.neoforge.common.util.FakePlayer(level,new com.mojang.authlib.GameProfile(new UUID(0,0xCA11),"ProgrammerCanon"));actor.setGameMode(GameType.SURVIVAL);return actor;}
 private static ItemStack place(ServerLevel level,ServerPlayer actor,BlockPos root,Direction face,boolean creative){var block=ProgrammerCanonicalMode.block();for(int part=0;part<4;part++)level.getChunkAt(NativeProgrammerBlock.cell(root,face,part));level.setBlock(root.below(),Blocks.STONE.defaultBlockState(),3);actor.setPos(root.getX()+.5,root.getY(),root.getZ()-3);actor.setYRot(face.getOpposite().toYRot());actor.setGameMode(creative?GameType.CREATIVE:GameType.SURVIVAL);var held=new ItemStack(BuiltInRegistries.ITEM.get(ProgrammerCanonicalMode.ID),2);actor.setItemInHand(InteractionHand.MAIN_HAND,held);need(held.useOn(new UseOnContext(actor,InteractionHand.MAIN_HAND,new BlockHitResult(new Vec3(root.getX()+.5,root.getY(),root.getZ()+.5),Direction.UP,root.below(),false))).consumesAction(),"actual canonical ItemStack.useOn");need(held.getCount()==(creative?2:1),"Survival/Creative source count");for(int part=0;part<4;part++){var pos=NativeProgrammerBlock.cell(root,face,part);var state=level.getBlockState(pos);need(state.is(block)&&state.getValue(NativeProgrammerBlock.FACING)==face&&state.getValue(NativeProgrammerBlock.PART)==part,"exact canonical four-cell metadata");need(part==0?level.getBlockEntity(pos) instanceof NativeProgrammerEntity owner&&owner.getType()==ProgrammerCanonicalMode.type():level.getBlockEntity(pos)==null,"one canonical token owner");var pick=block.getCloneItemStack(state,new BlockHitResult(Vec3.atCenterOf(pos),face,pos,false),level,pos,actor);need(pick.is(block.asItem())&&pick.getCount()==1&&!pick.has(DataComponents.CUSTOM_DATA)&&!pick.has(DataComponents.BLOCK_ENTITY_DATA),"all-part pick is plain without physical inventory");}return held;}
 private static NativeProgrammerEntity owner(ServerLevel level){return (NativeProgrammerEntity)level.getBlockEntity(BASE);}
 private static void saved(ServerLevel level){var owner=owner(level);need(owner!=null&&!owner.inert()&&owner.getType()==ProgrammerCanonicalMode.type(),"saved public entity identity");need(owner.getItem(0).getCount()==1&&owner.getItem(1).isEmpty()&&owner.getItem(2).getCount()==1,"sole saved Master/result owners");need(NativeCredentialItems.company(owner.getItem(2))==4&&owner.journalView()!=null&&owner.journalView().journal.title.equals("Canonical journal"),"saved programmed company and journal");var original=NativeCredentialItems.legacyCredentialData(owner.getItem(2));need(original.getCompound("ForgeCaps").getCompound("fixture:owned_item").getByteArray("Bytes").length==3&&original.getCompound("tag").getString("CanonicalPrivate").equals("PRIVATE_CANONICAL_ITEM"),"Program retains complete original item/capability envelope");need(!owner.getUpdateTag(level.registryAccess()).toString().contains("PRIVATE_CANONICAL_ITEM"),"normal DTO excludes physical private data");var chest=(ChestBlockEntity)level.getBlockEntity(BASE.east(4));need(chest!=null&&chest.getItem(0).is(ProgrammerCanonicalMode.block().asItem())&&chest.getItem(0).getCount()==1,"durable source stack remains one");need(level.getCapability(net.neoforged.neoforge.capabilities.Capabilities.ItemHandler.BLOCK,BASE,Direction.UP)==null,"no synthetic item capability");}
 @SubscribeEvent public static void started(ServerStartedEvent event){if(!enabled())return;var server=event.getServer();try{ProgrammerCanonicalMode.validate();var level=server.overworld();if(System.getProperty("vandorlabs.transmitterPhase").endsWith("read")){for(var pos:new BlockPos[]{BASE,BASE.east(4)}){level.setChunkForced(pos.getX()>>4,pos.getZ()>>4,true);level.getChunkAt(pos);}ProgrammerTimelineChecks.load(level,BASE.south(128));reading=true;return;}var actor=actor(level);var block=ProgrammerCanonicalMode.block();int index=0;for(var face:Direction.Plane.HORIZONTAL)for(boolean creative:new boolean[]{false,true}){var root=BASE.east(16+index++*8);place(level,actor,root,face,creative);need(level.getBlockState(root).getDestroySpeed(level,root)==3.5F&&block.getExplosionResistance()==3.5F,"Source hardness/final explosion resistance");level.removeBlock(root,false);}
  var remaining=place(level,actor,BASE,Direction.NORTH,false);level.setBlock(BASE.east(4),Blocks.CHEST.defaultBlockState(),3);((ChestBlockEntity)level.getBlockEntity(BASE.east(4))).setItem(0,remaining);actor.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);actor.setPos(BASE.getX()+.5,BASE.getY(),BASE.getZ()-2);var owner=owner(level);owner.setItem(0,NativeCredentialItems.dataChip(4));var raw=new CompoundTag();raw.putString("id","vandorlabs:data_chip");raw.putByte("Count",(byte)1);raw.putShort("Damage",(short)0);var tag=new CompoundTag();tag.putString("CanonicalPrivate","PRIVATE_CANONICAL_ITEM");raw.put("tag",tag);var caps=new CompoundTag();var owned=new CompoundTag();owned.putByteArray("Bytes",new byte[]{7,19,43});caps.put("fixture:owned_item",owned);raw.put("ForgeCaps",caps);owner.setItem(1,NativeCredentialItems.readStack(raw,level.registryAccess()));need(owner.configure(actor,new NativeProgrammerDraft(false,true,"Canonical journal",List.of("One complete retained result")))&&owner.program(actor),"canonical Program consumes and preserves opaque item envelope");for(int tick=0;tick<80;tick++)owner.tick();saved(level);
  ProgrammerMiningChecks.run(level,block,actor,BASE.south(32));ProgrammerContactChecks.run(level,block,actor,BASE.south(96));ProgrammerTimelineChecks.write(level,block,actor,BASE.south(128));saved(level);server.saveEverything(true,true,true);System.out.println("[vandorlabs][programmer-canonical] write PASS checks="+checks);
 }catch(Throwable failure){failure.printStackTrace();System.out.println("[vandorlabs][programmer-canonical] FAIL "+failure);}finally{if(!reading)server.halt(false);}}
 @SubscribeEvent public static void tick(net.neoforged.neoforge.event.tick.LevelTickEvent.Post event){if(!reading||!(event.getLevel() instanceof ServerLevel level)||level!=level.getServer().overworld())return;try{need(++ticks<400,"canonical restart timeout");if(!ProgrammerTimelineChecks.readReady(level))return;saved(level);var output=owner(level).getItem(2).copy();watch=true;drops.clear();var actor=actor(level);actor.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.WOODEN_PICKAXE));actor.setPos(BASE.getX()+.5,BASE.getY(),BASE.getZ()-2);need(actor.gameMode.destroyBlock(BASE),"actual canonical survival mining");watch=false;need(drops.stream().filter(stack->stack.is(ProgrammerCanonicalMode.block().asItem())).mapToInt(ItemStack::getCount).sum()==1,"canonical plain drop exactly once");need(drops.stream().filter(stack->stack.is(NativeCredentialItems.DATA_CHIP.get())).mapToInt(ItemStack::getCount).sum()==2&&drops.stream().anyMatch(stack->ItemStack.matches(stack,output)),"complete Master/result ejected once after restart");for(int part=0;part<4;part++)need(level.getBlockState(NativeProgrammerBlock.cell(BASE,Direction.NORTH,part)).isAir(),"all canonical cells removed after mining");System.out.println("[vandorlabs][programmer-canonical] read PASS checks="+checks);reading=false;level.getServer().halt(false);}catch(Throwable failure){failure.printStackTrace();System.out.println("[vandorlabs][programmer-canonical] FAIL "+failure);reading=false;level.getServer().halt(false);}}
 @SubscribeEvent public static void joined(net.neoforged.neoforge.event.entity.EntityJoinLevelEvent event){if(watch&&event.getLevel() instanceof ServerLevel&&event.getEntity() instanceof ItemEntity entity)drops.add(entity.getItem().copy());}
}
